[
  {
    "statement": "Several studies have examined the effects of different farming practices on bat populations.",
    "citations": []
  },
  {
    "statement": "Five of seven studies comparing organic and conventional farming showed no difference in the number of bat species.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Two studies comparing organic and conventional farming found a greater number of bat species on organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "In terms of bat activity, five of nine studies found no difference between organic and conventional farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Four studies reported higher overall bat activity on organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Some studies in the UK and France indicated higher activity for certain bat species in specific habitats on organic farms.",
    "citations": [
      "961"
    ]
  },
  {
