  {
    "statement": "Two UK studies suggest that trimming hedges less frequently could be advantageous for bats.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "Hedges that had not been trimmed for three or more years were found to have a higher number of bat species when compared to hedges trimmed more recently.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "Hedges untrimmed for three or more years had increased activity for two out of eight bat species or species groups when compared to hedges trimmed more recently.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "A separate study discovered no variance in pipistrelle activity between hedges managed for wildlife under agri-environment schemes and hedges on conventional farms.",
    "citations": [
      "1943"
    ]
  }
]

[
