[
  {
    "statement": "To mitigate the disturbance and loss of bat roosts during building developments, several actions can be taken.",
    "citations": []
  },
  {
    "statement": "One approach to mitigate disturbance is to create alternative roosts for bats.",
    "citations": []
  },
  {
    "statement": "The success of creating alternative roosts for bats is varied.",
    "citations": []
  },
  {
    "statement": "In some cases, bats did not use the alternative roosts provided.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "In some instances, bat boxes or lofts were used at 13-74% of development sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Purpose-built roosts have been found to be used in higher or similar numbers to the original roosts in some cases.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "In other cases, purpose-built roosts have been found to be used in lower numbers than the original roosts.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "New bat boxes or lofts are four times less likely to be used by returning bats than roosts that are retained during development.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Another action is the legal protection of bats through licensing during development.",
    "citations": []
  },
  {
    "statement": "A UK review found that 68% of bat roosts were destroyed under licensed activities.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "81% of licensees did not carry out post-development monitoring to assess the use of the installed roost structures.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Some compensation roosts provided under license are used by bats.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "One study found that 5 of 28 compensation roosts provided under license were used.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Another review found that between 31% and 67% of compensation roosts provided under license were used.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Retaining existing bat roosts and access points within developments is another option for mitigation.",
    "citations": []
  },
  {
    "statement": "One study found similar numbers of bats roosting in an attic after access points were retained during renovations.",
    "citations": [
      "947"
    ]
  },
  {
    "statement": "A UK review found that two-thirds of retained and modified roosts were used after development.",
    "citations": [
      "947"
    ]
  },
  {
    "statement": "Retained roosts were more likely to be used by bats than newly created ones.",
    "citations": [
      "947"
    ]
  },
  {
    "statement": "Providing training on bat ecology and conservation to the building and development sector is an option.",
    "citations": []
  },
  {
    "statement": "No studies were found to evaluate the effectiveness of providing training on bat ecology and conservation.",
    "citations": [
      "997"
    ]
  },
  {
    "statement": "No studies were found on the effectiveness of installing sound barriers near bat roosts.",
    "citations": [
      "2023"
    ]
  }
